// ── ANTI-PATTERN: Singleton as global state dump ───────────────
class AppState {
  static #instance = null;
  constructor() {
    this.user        = null;   // auth concern
    this.cartItems   = [];     // shopping concern
    this.theme       = 'light';// UI concern
    this.featureFlags= {};     // ops concern
  }
  static getInstance() {
    if (!AppState.#instance) AppState.#instance = new AppState();
    return AppState.#instance;
  }
}
// Problem: any module can mutate any field
// Tests: AppState.#instance = null; // must hack private field to reset
const state = AppState.getInstance();
state.user = { id: 1, name: 'Alice' };  // who set this? when?
state.cartItems.push({ id: 'p1' });     // mutation invisible to other readers

// ── REFACTOR: split by concern, inject as dependency ───────────
class AuthStore {
  constructor() { this._user = null; }
  login(user)  { this._user = user; }
  getUser()    { return this._user; }
}
class CartStore {
  constructor() { this._items = []; }
  add(item)    { this._items.push(item); }
  getItems()   { return [...this._items]; }  // immutable copy
}
// Each store is injected — no hidden global references
const auth = new AuthStore();
const cart = new CartStore();
auth.login({ id: 1, name: 'Alice' });
cart.add({ id: 'p1' });
console.log(auth.getUser().name);  // Alice
console.log(cart.getItems());      // [ { id: 'p1' } ]
// In tests: just pass new AuthStore() — no Singleton teardown needed

// ── ANTI-PATTERN: Premature Factory ────────────────────────────
class UserFactory {                 // adds a file, zero benefit
  static create(data) { return new User(data); }   // trivial delegation
}
// GOOD — until you have 2+ types or complex init, just:
class User {
  constructor({ id, name, role = 'viewer' }) {
    this.id = id; this.name = name; this.role = role;
  }
}
const u = new User({ id: 42, name: 'Bob' });
console.log(u.role); // viewer

// ── WHEN Factory IS justified: multiple types + runtime decision ─
function createNotifier(channel, config) {
  if (channel === 'email')  return new EmailNotifier(config);
  if (channel === 'sms')    return new SmsNotifier(config);
  if (channel === 'push')   return new PushNotifier(config);
  throw new Error(`Unknown channel: ${channel}`);
}
// Rule: Factory earns its keep when there are 2+ concrete types.

class EmailNotifier { send(msg) { console.log(`Email: ${msg}`); } }
class SmsNotifier   { send(msg) { console.log(`SMS: ${msg}`); } }
class PushNotifier  { send(msg) { console.log(`Push: ${msg}`); } }

const notifier = createNotifier('sms', {});
notifier.send('Your order shipped!'); // SMS: Your order shipped!

// ── Pattern Fever: Event Emitter for simple sequential logic ───
const EventEmitter = require('events');
const bus = new EventEmitter();

// ANTI-PATTERN: wiring sequential steps through events
bus.on('step1:done', () => bus.emit('step2:start'));
bus.on('step2:start', () => bus.emit('step2:done'));
bus.on('step2:done', () => console.log('Pipeline complete'));
bus.emit('step1:done');
// Problem: control flow is invisible — you must trace event registrations
// to understand execution order. Every new step requires two listeners.

// GOOD: simple sequential logic stays sequential
function runPipeline() {
  step1();
  step2();
  console.log('Pipeline complete');
}
function step1() { /* ... */ }
function step2() { /* ... */ }
runPipeline(); // readable, debuggable, no hidden indirection

// Reserve EventEmitter for TRUE fan-out (unknown N subscribers):
const orderEvents = new EventEmitter();
orderEvents.on('order:placed', sendConfirmationEmail);   // subscriber 1
orderEvents.on('order:placed', updateInventory);         // subscriber 2
orderEvents.on('order:placed', notifyWarehouse);         // subscriber 3
// Here the emitter is justified: the order module does NOT know who listens.

function sendConfirmationEmail(order) { console.log('Email sent for', order.id); }
function updateInventory(order)       { console.log('Inventory updated for', order.id); }
function notifyWarehouse(order)       { console.log('Warehouse notified for', order.id); }
orderEvents.emit('order:placed', { id: 'ORD-99' });

// ── Needless abstraction: over-engineered for one endpoint ─────
// BAD — 4 layers to serve GET /users
class BaseController    { handle() {} }
class AbstractCrud      extends BaseController { list() {} }
class GenericResource   extends AbstractCrud  { paginate() {} }
class UserController    extends GenericResource {
  list() { return [{ id: 1 }]; }  // the only real work
}
// GOOD — one file, no hierarchy
function listUsers() { return [{ id: 1 }]; } // done. extend when a second endpoint proves the pattern
console.log(listUsers());

